insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-ob-288', 'chemistry-organic-chemistry-some-basic-principles-and-techniques', 'chemistry', 'If an organic compound contains both nitrogen and sulphur, extra care is needed in the nitrogen test because thiocyanate may form instead of cyanide; a reliable extra observation is the', '["yellow AgI without acid","blood-red colour with FeCl3 from NaSCN","violet iodine-starch in the extract without fusion","white fumes of HCl only"]'::jsonb, 1, 'NaSCN gives blood red with FeCl3. If only cyanide is wanted for Prussian blue, the extract is boiled with FeSO4 and Fe3+ under the usual nitrogen procedure, sometimes after decomposing thiocyanate.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
